begin;
create or replace function internal.measure_intervention(target uuid,followup_id uuid,minimum_change numeric)returns uuid language plpgsql security definer set search_path=''as $$declare i app.interventions;b app.result_revisions;f app.result_revisions;existing app.outcome_measurements;oid uuid;delta numeric;state text;reason_text text;begin select*into i from app.interventions where school_id="authorization".school_id()and id=target for update;if not found or not"authorization".can_access_intervention(i.school_id,i.id,true)then raise exception 'Measurement denied'using errcode='42501';end if;
select*into b from app.result_revisions where school_id=i.school_id and id=i.baseline_result_id;select*into f from app.result_revisions where school_id=i.school_id and id=followup_id;
if minimum_change is null or minimum_change<=0 or minimum_change>100000 or f.id is null or i.completed_at is null or f.assessment_id is distinct from i.follow_up_assessment_id or f.learner_id<>i.learner_id or f.reference_id<>b.reference_id or f.reference_version<>b.reference_version or f.max_score<>b.max_score or f.created_at<=i.completed_at or not exists(select 1 from app.submissions s where s.school_id=f.school_id and s.id=f.submission_id and s.submitted_at>i.completed_at)then raise exception 'Incompatible measured evidence'using errcode='22023';end if;
select*into existing from app.outcome_measurements where school_id=i.school_id and intervention_id=i.id;if found then if existing.follow_up_result_id<>followup_id or existing.minimum_change<>minimum_change then raise exception 'Measurement immutable'using errcode='22023';end if;return existing.id;end if;
delta:=f.score-b.score;state:=case when delta>=minimum_change then'improved'when abs(delta)<minimum_change then'no_meaningful_change'else'inconclusive'end;reason_text:=case when delta<=-minimum_change then'FOLLOW_UP_LOWER'else'OBSERVED_RAW_SCORE_CHANGE'end;
insert into app.outcome_measurements(school_id,intervention_id,learner_id,baseline_result_id,follow_up_result_id,status,difference,minimum_change,baseline_score,baseline_max_score,follow_up_score,follow_up_max_score,reason)values(i.school_id,i.id,i.learner_id,b.id,f.id,state,delta,minimum_change,b.score,b.max_score,f.score,f.max_score,reason_text)returning id into oid;update app.interventions set status='MEASURED'where school_id=i.school_id and id=i.id;return oid;end$$;
create or replace function internal.decide_recommendation(target uuid,choice text,reason_text text,edited_title text,edited_instructions text)returns uuid language plpgsql security definer set search_path=''as $$declare r app.recommendations;d app.human_decisions;begin select*into r from app.recommendations where school_id="authorization".school_id()and id=target for update;if not found or not"authorization".can_manage_baseline(r.school_id,r.baseline_result_id)then raise exception 'Recommendation denied'using errcode='42501';end if;if choice is null or choice not in('APPROVE','REJECT')or reason_text is null or length(reason_text)not between 1 and 4000 then raise exception 'Invalid decision'using errcode='22023';end if;
select*into d from app.human_decisions where school_id=r.school_id and recommendation_id=r.id;if found then if d.decision<>choice or d.reason<>reason_text or (choice='APPROVE'and exists(select 1 from app.interventions i where i.school_id=r.school_id and i.recommendation_id=r.id and(i.title is distinct from coalesce(edited_title,r.activity_title)or i.instructions is distinct from coalesce(edited_instructions,r.instructions))))then raise exception 'Decision immutable'using errcode='22023';end if;return r.id;end if;
insert into app.human_decisions(school_id,recommendation_id,decision,reason,actor_id)values(r.school_id,r.id,choice,reason_text,"authorization".actor_id());update app.recommendations set status=case when choice='APPROVE'then'APPROVED'else'REJECTED'end where school_id=r.school_id and id=r.id;
if choice='APPROVE'then insert into app.interventions(school_id,recommendation_id,learner_id,reference_id,baseline_result_id,title,instructions)values(r.school_id,r.id,r.learner_id,r.reference_id,r.baseline_result_id,coalesce(edited_title,r.activity_title),coalesce(edited_instructions,r.instructions));end if;return r.id;end$$;
create function internal.improvement_event_exists(event_key text)returns boolean language sql stable security definer set search_path=''as $$select "authorization".improvement_access("authorization".school_id())and exists(select 1 from internal.outbox_events where school_id="authorization".school_id()and deduplication_key=event_key)$$;
revoke execute on function internal.improvement_event_exists(text)from public,anon,authenticated,service_role,cuevo_worker;grant execute on function internal.improvement_event_exists(text)to cuevo_api;
commit;
